pseudocode:
1: let nums = n.toString().split('').map(Number);
2: let i = nums.length - 2;
3: while (i >= 0 && nums[i] >= nums[i+1]) i--;
4: if (i < 0) return -1;
5: let j = nums.length - 1;
6: while (nums[j] <= nums[i]) j--;
7: [nums[i], nums[j]] = [nums[j], nums[i]];
8: nums.splice(i + 1, nums.length - i - 1, ...nums.slice(i + 1).reverse());
9: return parseInt(nums.join(''));
